create table if not exists public.cms_inquiries(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),status text not null default'new'check(status in('new','contacted','qualified','closed')),subject text not null default'Website enquiry',name text not null,company text not null default'',job_title text not null default'',country text not null default'',email text not null,phone text not null default'',business_type text not null default'',message text not null,language text not null default'en',source text not null default'website',admin_notes text not null default'');
create index if not exists cms_inquiries_created_idx on public.cms_inquiries(created_at desc);create index if not exists cms_inquiries_status_created_idx on public.cms_inquiries(status,created_at desc);alter table public.cms_inquiries enable row level security;revoke all on table public.cms_inquiries from anon,authenticated;grant insert on table public.cms_inquiries to anon,authenticated;grant select,update on table public.cms_inquiries to authenticated;
drop policy if exists "Website visitors create enquiries" on public.cms_inquiries;create policy "Website visitors create enquiries" on public.cms_inquiries for insert to anon,authenticated with check(status='new'and admin_notes=''and char_length(name)between 1 and 160 and char_length(email)between 3 and 320 and char_length(message)between 1 and 8000 and char_length(company)<=240 and char_length(phone)<=80);
drop policy if exists "CMS admins read enquiries" on public.cms_inquiries;create policy "CMS admins read enquiries" on public.cms_inquiries for select to authenticated using(exists(select 1 from public.cms_admins a where a.user_id=auth.uid()));
drop policy if exists "CMS admins update enquiries" on public.cms_inquiries;create policy "CMS admins update enquiries" on public.cms_inquiries for update to authenticated using(exists(select 1 from public.cms_admins a where a.user_id=auth.uid()))with check(exists(select 1 from public.cms_admins a where a.user_id=auth.uid()));
